#include<bits/stdc++.h>
#define mod 998244353

using namespace std;

int main(){
  int n,m;
  cin >> n >> m;
  vector<string> s(n);
  for(auto &nx : s){cin >> nx;}
  vector<long long> dp(1<<m,0);
  dp[(1<<m)-1]=1;
  for(int i=0;i<n;i++){
    vector<long long> ndp=dp;
    for(int j=0;j<m;j++){

      vector<long long> work(1<<m,0);
      if(s[i][j]!='1'){
        // put 0
        for(int k=0;k<(1<<m);k++){
          if(k&(1<<j)){
            work[k^(1<<j)]+=ndp[k];
            work[k^(1<<j)]%=mod;
          }
          else{
            work[k]+=ndp[k];
            work[k]%=mod;
          }
        }
      }
      if(s[i][j]!='0'){
        // put 1
        for(int k=0;k<(1<<m);k++){
          if(k&(1<<j)){
            work[k]+=ndp[k];
            work[k]%=mod;
          }
        }
      }
      ndp=work;

      bool ok=true;
      for(int k=0;k<=j;k++){
        if(s[i][k]=='0'){ok=false;break;}
      }
      if(!ok){continue;}
      for(int k=0;k<(1<<m);k++){
        if(k&(1<<j)){continue;}
        ndp[k]+=dp[k];
        ndp[k]%=mod;
      }
    }
    dp=ndp;
  }

  long long res=0;
  for(auto &nx : dp){res+=nx;res%=mod;}
  cout << res << "\n";
  return 0;
}
